import{_ as o,o as e,c as a,ai as r}from"./chunks/framework.scx6l_IK.js";const l=JSON.parse('{"title":"金刚经23分-净心行善","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经23分-净心行善.md","filePath":"60-原文段落/金刚经23分-净心行善.md","lastUpdated":1778155802000}'),p={name:"60-原文段落/金刚经23分-净心行善.md"};function _(s,t,n,c,u,d){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="金刚经23分-净心行善" tabindex="-1">金刚经23分-净心行善 <a class="header-anchor" href="#金刚经23分-净心行善" aria-label="Permalink to &quot;金刚经23分-净心行善&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/23了空居士讲《金刚经》-第二十三分净心行善分20170310">23了空居士讲《金刚经》-第二十三分净心行善分20170310</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>是法平等，无有高下，是名阿耨多罗三藐三菩提。</strong></p><p>&quot;是法&quot;就是指阿耨多罗三藐三菩提这个法，但是这个阿耨多罗三藐三菩提法跟其他万法又不一样，它是无法可得，方证阿耨多罗三藐三菩提。这句话连起来就是阿耨多罗三藐三菩提法，它是最平等的一种状态。&quot;是法平等，无有高下&quot;，面对的一切现象，他没有厚此薄彼、高此低彼的这种心态，也就是说他是一种最清净的心的状态。</p><p>如果你说阿耨多罗三藐三菩提和其他的法没有高下，本来阿耨多罗三藐三菩提就不是一个固定的东西，没有一个形象的东西，所以怎么能比较呢？太阳和月亮都不一样了，你不可能将太阳当月亮，将月亮当太阳吧。牛粪和朱古力都是黑色，那你敢吃牛粪吗？无有高下，真的无有高下吗？妈妈和老婆肯定不一样吧，不能将妈妈当老婆，将老婆当妈妈吧。有些流行就跟流行感冒一样，真的没用的。</p><p>平等心不是说牛粪和朱古力无区别——平等是指心态上不分别高下，做事时还是要分清。坐飞机和走路都能到北京，不要用自己的法门评判别人的。但平等心不等于没有判断——吃饭不能塞进眼睛里，这是智慧，不是不分别。</p><p><strong>以无我、无人、无众生、无寿者，修一切善法，即得阿耨多罗三藐三菩提。</strong></p><p>那么佛祖前边说&quot;是法平等，无有高下，是名阿耨多罗三藐三菩提。&quot;那人家说又有一个法，那前边你说无法可得，怎么又搞出一个法？其实这个阿耨多罗三藐三菩提是不得已而取的一个假名，佛祖就告诉我们这个阿耨多罗三藐三菩提是没办法独立存在的，它在什么时候显现呢？就是当你以无我无人无众生无寿者修一切善法，那个时候就是阿耨多罗三藐三菩提的状态。即得阿耨多罗三藐三菩提，你们不要以为你们在修善法之后就得这个阿耨多罗三藐三菩提，不是，在修善法的时候，同时就是阿耨多罗三藐三菩提，千万不要以为有个因果关系，你在以无我无人无众生无寿者修一切善法之后就得了个阿耨多罗三藐三菩提，不是，没有得，你在做的时候那个状态就是阿耨多罗三藐三菩提。明树，我这么一讲，你们就觉得得阿耨多罗三藐三菩提也很容易的嘛，确实是很容易的，当然要失去也很容易，只要你一着相，唉，我为什么要这么做？我何苦啊？完了，又是落到贪嗔痴了，所以这个佛法的奥妙就是在这一点上，你们不要以为阿耨多罗三藐三菩提遥不可及，高不可攀，不是，一念相应一念佛啊，就这么简单。</p><p><strong>须菩提，所言善法者，如来说即非善法，是名善法。</strong></p><p>噢，佛祖大智慧，他怕我们说修一切善法，说佛祖啊什么是善法？说你可能说佛祖有没有说善法？七佛通偈：&quot;诸恶莫作，众善奉行，自净其意。&quot;这些都是善法，那么有标准吗？很难拿一个绝对的标准，只能在事上具体去分析，所以佛祖就怕我们落入一个教条主义，框框套套的，他就说须菩提，所言善法者，如来说即非善法，是名善法。说你们不要以为有个固定的东西，你们具体去做才知道。</p>',11)])])}const q=o(p,[["render",_]]);export{l as __pageData,q as default};
